<script setup>
import {computed,ref} from 'vue';import {router,useForm,usePage} from '@inertiajs/vue3';import PortalLayout from '../../../Layouts/PortalLayout.vue';
defineProps({series:Object,exams:Array});const page=usePage();const hi=computed(()=>page.props.locale==='hi');const editing=ref(null);
const blank=()=>({title:'',description:'',access_type:'free',price:0,currency:'INR',status:'draft',starts_at:'',ends_at:'',max_enrollments:'',exam_ids:[]});
const form=useForm(blank());
function reset(){editing.value=null;form.reset();form.clearErrors();}
function submit(){const options={onSuccess:reset};editing.value?form.put('/admin/test-series/'+editing.value,options):form.post('/admin/test-series',options);}
function edit(s){editing.value=s.id;Object.assign(form,{title:s.title,description:s.description||'',access_type:s.access_type,price:Number(s.price),currency:s.currency,status:s.status,starts_at:s.starts_at?s.starts_at.replace(' ','T').slice(0,16):'',ends_at:s.ends_at?s.ends_at.replace(' ','T').slice(0,16):'',max_enrollments:s.max_enrollments||'',exam_ids:s.exams?.map(e=>String(e.id))||[]});}
function status(s,v){if(confirm('Change series status to '+v+'?'))router.patch('/admin/test-series/'+s.id+'/status',{status:v});}
</script>
<template><PortalLayout portal="admin" :title="hi?'टेस्ट सीरीज़ प्रबंधन':'Test series management'" :subtitle="hi?'परीक्षाओं को फ्री या पेड सीरीज़ में व्यवस्थित करें।':'Group published exams into free or paid learning packages.'">
<div class="grid gap-6 xl:grid-cols-[minmax(0,1fr)_420px]"><section class="overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="p-3">Series</th><th class="p-3">Access</th><th class="p-3">Exams</th><th class="p-3">Students</th><th class="p-3">Status</th><th class="p-3">Actions</th></tr></thead><tbody>
<tr v-for="s in series.data" :key="s.id" class="border-t"><td class="p-3 font-bold">{{s.title}}</td><td class="p-3 capitalize">{{s.access_type==='paid'?s.currency+' '+s.price:'Free'}}</td><td class="p-3">{{s.exams_count}}</td><td class="p-3"><a :href="'/admin/test-series/'+s.id+'/enrollments'" class="text-indigo-700 underline">{{s.enrollments_count}}</a></td><td class="p-3 capitalize">{{s.status}}</td><td class="p-3"><button @click="edit(s)" class="mr-2 text-indigo-700">Edit</button><select :value="s.status" @change="status(s,$event.target.value)" class="rounded border p-1"><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></td></tr>
<tr v-if="!series.data.length"><td colspan="6" class="p-8 text-center text-slate-500">No test series yet.</td></tr></tbody></table></section>
<aside class="h-fit rounded-xl border bg-white p-5"><h2 class="text-lg font-extrabold">{{editing?'Edit test series':'Create test series'}}</h2><form @submit.prevent="submit" class="mt-4 space-y-3">
<label class="block text-sm font-semibold">Title<input v-model="form.title" required maxlength="180" class="mt-1 w-full rounded-lg border p-2"></label>
<label class="block text-sm font-semibold">Description<textarea v-model="form.description" rows="3" class="mt-1 w-full rounded-lg border p-2"/></label>
<div class="grid grid-cols-2 gap-2"><label class="text-sm font-semibold">Access type<select v-model="form.access_type" class="mt-1 w-full rounded border p-2"><option value="free">Free</option><option value="paid">Paid</option></select></label>
<label v-if="form.access_type==='paid'" class="text-sm font-semibold">Price (INR)<input v-model.number="form.price" type="number" min="0.01" step="0.01" required class="mt-1 w-full rounded border p-2"></label></div>
<div class="grid grid-cols-2 gap-2"><label class="text-sm font-semibold">Starts at<input v-model="form.starts_at" type="datetime-local" class="mt-1 w-full rounded border p-2"></label><label class="text-sm font-semibold">Ends at<input v-model="form.ends_at" type="datetime-local" class="mt-1 w-full rounded border p-2"></label></div>
<label class="block text-sm font-semibold">Maximum enrollments<input v-model="form.max_enrollments" type="number" min="1" class="mt-1 w-full rounded border p-2" placeholder="Unlimited"></label>
<label v-if="!editing" class="block text-sm font-semibold">Initial status<select v-model="form.status" class="mt-1 w-full rounded border p-2"><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></label>
<label class="block text-sm font-semibold">Published exams ({{form.exam_ids.length}} selected)<select v-model="form.exam_ids" multiple size="8" required class="mt-1 w-full rounded border p-2"><option v-for="e in exams" :key="e.id" :value="String(e.id)">#{{e.id}} · {{e.title}}</option></select><span class="text-xs font-normal text-slate-500">Use Ctrl to select multiple exams. Selection order is retained.</span></label>
<div v-for="(error,key) in form.errors" :key="key" class="text-xs text-rose-600">{{error}}</div><div class="flex gap-2"><button :disabled="form.processing" class="flex-1 rounded-lg bg-indigo-600 px-4 py-2 font-bold text-white">{{editing?'Save changes':'Create series'}}</button><button v-if="editing" type="button" @click="reset" class="rounded-lg border px-3">Cancel</button></div>
</form></aside></div></PortalLayout></template>